```python
def is_divisible_by_all_nonzero_digits(number):
    digits = [int(d) for d in str(number)]
    for digit in digits:
        if digit != 0 and number % digit != 0:
            return False
    return True

def find_smallest_five_digit_number():
    for num in range(10222, 100000):
        if is_divisible_by_all_nonzero_digits(num):
            return num

smallest_number = find_smallest_five_digit_number()
print(smallest_number)
```
